import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  trackLoginAttempt(event) {
    if (typeof gtag !== 'undefined') {
      gtag('event', 'login_attempt', {
        event_category: 'authentication',
        event_label: 'form_submit'
      });
    }
  }

  trackSignupAttempt(event) {
    if (typeof gtag !== 'undefined') {
      gtag('event', 'signup_attempt', {
        event_category: 'authentication',
        event_label: 'first_login_form_submit'
      });
    }
  }

  trackFormInteraction(event) {
    const formType = event.target.closest('form').dataset.formType || 'unknown';

    if (typeof gtag !== 'undefined') {
      gtag('event', 'form_interaction', {
        event_category: 'authentication',
        event_label: formType
      });
    }
  }

  trackPasswordVisibilityToggle(event) {
    if (typeof gtag !== 'undefined') {
      gtag('event', 'password_visibility_toggle', {
        event_category: 'authentication',
        event_label: 'show_hide_password'
      });
    }
  }
}

